@import "tailwindcss";

@theme {
  --font-heading: "Atkinson Hyperlegible Next", sans-serif;
  --font-sans: "Lexend", sans-serif;
  --font-label: "Lexend", sans-serif;
  --font-mono: "Roboto Mono", monospace;

  --color-background: var(--background);
  --color-on-background: var(--on-background);
  --color-surface: var(--surface);
  --color-on-surface: var(--on-surface);
  --color-on-surface-variant: var(--on-surface-variant);
  --color-surface-container: var(--surface-container);
  --color-surface-variant: var(--surface-variant);
  --color-outline: var(--outline);
  --color-outline-variant: var(--outline-variant);

  --color-primary: var(--primary);
  --color-on-primary: var(--on-primary);
  --color-primary-container: var(--primary-container);
  --color-on-primary-container: var(--on-primary-container);

  --color-secondary: var(--secondary);
  --color-on-secondary: var(--on-secondary);
  --color-secondary-container: var(--secondary-container);
  --color-on-secondary-container: var(--on-secondary-container);

  --color-tertiary: var(--tertiary);
  --color-on-tertiary: var(--on-tertiary);
  --color-tertiary-container: var(--tertiary-container);
  --color-on-tertiary-container: var(--on-tertiary-container);

  --color-error: var(--error);
  --color-on-error: var(--on-error);
  --color-error-container: var(--error-container);
  --color-on-error-container: var(--on-error-container);

  --color-warning: var(--warning);
  --color-on-warning: var(--on-warning);
  --color-warning-container: var(--warning-container);
  --color-on-warning-container: var(--on-warning-container);

  --color-success: var(--success);
  --color-on-success: var(--on-success);
  --color-success-container: var(--success-container);
  --color-on-success-container: var(--on-success-container);

  --color-neutral: var(--neutral);
  --color-on-neutral: var(--on-neutral);
  --color-neutral-container: var(--neutral-container);
  --color-on-neutral-container: var(--on-neutral-container);

  --border-width-default: 1px;
  --border-width-emphasis: 2px;
  --border-width-accent: 4px;
  --border-default: 1px;
  --border-emphasis: 2px;
  --border-accent: 4px;

  --radius: 0.5rem;
  --radius-none: 0px;
  --radius-sm: 0.25rem;
  --radius-default: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-full: 9999px;
}

/* `static` always emits these to :root so inline styles and raw CSS can use var(--shadow-*), var(--duration-*) etc. */
@theme static {
  /* Layered Ambient & Modal Shadows (Umbra + Penumbra) */
  --shadow-ambient: 0 1px 3px rgba(26, 28, 30, 0.04), 0 4px 12px rgba(26, 28, 30, 0.06);
  --shadow-ambient-hover: 0 2px 4px rgba(26, 28, 30, 0.04), 0 8px 20px rgba(26, 28, 30, 0.08);
  --shadow-modal: 0 2px 6px rgba(26, 28, 30, 0.04), 0 8px 20px rgba(26, 28, 30, 0.06), 0 20px 48px rgba(26, 28, 30, 0.12);

  /* Motion Tokens */
  --duration-stagger: 40ms;
  --duration-micro: 80ms;
  --duration-quick: 150ms;
  --duration-fast: 250ms;
  --duration-medium: 350ms;
  --duration-slow: 400ms;
  --duration-very-slow: 500ms;
  --duration-emphasis: 500ms;

  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-smooth-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-exit: cubic-bezier(0.4, 0, 1, 1);
  --ease-in-out: ease-in-out;
  --ease-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);

  --scale-large: 0.96;
  --scale-medium: 0.97;
  --scale-small: 0.98;
  --scale-tiny: 0.99;

  --distance-micro: 4px;
  --distance-small: 6px;
  --distance-base: 8px;
  --distance-medium: 12px;
  --distance-roomy: 16px;

  --blur-small: 2px;
  --blur-medium: 3px;
}

@theme {
  /* Spacing & Layout Tokens (DESIGN.md) */
  --spacing-gutter: var(--gutter);
  --spacing-gutter-mobile: var(--gutter-mobile);
  --spacing-margin-mobile: var(--margin-mobile);
  --spacing-margin-tablet: var(--margin-tablet);
  --spacing-margin-desktop: var(--margin-desktop);
  --container-measure: var(--measure);
  --spacing-container-max: var(--container-max);
}

:root {
  color-scheme: light;
  accent-color: var(--primary);
  interpolate-size: allow-keywords;
  scrollbar-gutter: stable;
  font-synthesis: none;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  -webkit-tap-highlight-color: transparent;

  /* Safe Area Inset Tokens (Good CSS #47) */
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);

  --background: #F6F7FB;
  --on-background: #1a1c1e;
  --surface: #ffffff;
  --on-surface: #1a1c1e;
  --on-surface-variant: #434656;
  --surface-container: #EEF1F8;
  --surface-variant: #E1E6F0;
  --outline: #737688;
  --outline-variant: #C8D0E0;
  --primary: #0052FF;
  --on-primary: #ffffff;
  --primary-container: #dce6ff;
  --on-primary-container: #1a1c1e;
  --secondary: #00796B;
  --on-secondary: #ffffff;
  --secondary-container: #e0f2f1;
  --on-secondary-container: #1a1c1e;
  --tertiary: #F9A825;
  --on-tertiary: #1a1c1e;
  --tertiary-container: #fff0c2;
  --on-tertiary-container: #1a1c1e;
  --error: #ba1a1a;
  --on-error: #ffffff;
  --error-container: #ffdad6;
  --on-error-container: #1a1c1e;
  --warning: #8a5200;
  --on-warning: #ffffff;
  --warning-container: #ffe0b3;
  --on-warning-container: #1a1c1e;
  --success: #146c2e;
  --on-success: #ffffff;
  --success-container: #c8f5ce;
  --on-success-container: #1a1c1e;

  --neutral: #1a1c1e;
  --on-neutral: #ffffff;
  --neutral-container: #D5DCEB;
  --on-neutral-container: #1a1c1e;

  /* Spacing & Layout Tokens (DESIGN.md) */
  --spacing-base: 0.5rem;
  --gutter: 1.5rem;
  --gutter-mobile: 1rem;
  --margin-mobile: 1rem;
  --margin-tablet: 2rem;
  --margin-desktop: 4rem;
  --container-max: 80rem;
  --measure: 40rem;
  --header-height: 4rem;
}

/* Document-level overscroll containment, sticky anchor clearance & motion rules (Good CSS #45, #46) */
html {
  overscroll-behavior-y: none;
  scroll-padding-block-start: calc(var(--header-height, 4rem) + 1rem);
}

@media (any-pointer: coarse) {
  html {
    overscroll-behavior-y: auto;
  }
}

@media (prefers-reduced-motion: no-preference) {
  html {
    scroll-behavior: smooth;
  }
}

/* Tabular figures for tables, counters, metrics, and timestamps (Good CSS #21) */
td,
time,
[data-tabular-nums] {
  font-variant-numeric: tabular-nums;
}

/* Defensive input zoom prevention on iOS Safari while respecting body font floor (Good CSS #01) */
input,
textarea,
select {
  font-size: max(16px, 1rem);
}

/* Suppress native search clear button in WebKit/Blink to prevent double clear 'X' alongside custom clearable action */
input[type="search"]::-webkit-search-cancel-button,
input[type="search"]::-webkit-search-decoration,
input[type="search"]::-webkit-search-results-button,
input[type="search"]::-webkit-search-results-decoration {
  -webkit-appearance: none;
  appearance: none;
  display: none;
}

/* Prevent text selection highlight during rapid control activation (Good CSS #01) */
button,
[role="button"] {
  user-select: none;
  -webkit-user-select: none;
}

/* Border Width Token Utility Classes */
.border-default {
  border-width: 1px;
}

.border-emphasis {
  border-width: 2px;
}

.border-accent {
  border-width: 4px;
}

/* Material Symbols icon styling helper */
.material-symbols-outlined {
  font-family: 'Material Symbols Outlined';
  font-weight: normal;
  font-style: normal;
  font-size: 24px;
  line-height: 1;
  letter-spacing: normal;
  text-transform: none;
  display: inline-block;
  white-space: nowrap;
  word-wrap: normal;
  direction: ltr;
  -webkit-font-smoothing: antialiased;
}

/* Accessible high-visibility focus ring compatible with forced-colors mode */
*:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* Suppress UA default black focus outline on mouse/pointer clicks while preserving WCAG keyboard focus */
:focus:not(:focus-visible) {
  outline: none;
}

/* 1. Standard Form Controls (flush 2px focus ring) */
input:not([data-slot="combobox-input-group"] *):not([data-slot="autocomplete-input-group"] *):focus-visible,
select:focus-visible,
textarea:not([data-slot="prompt-input"] *):focus-visible,
[data-slot="select-trigger"]:focus-visible,
[data-slot="combobox-input-group"]:focus-within,
[data-slot="autocomplete-input-group"]:focus-within {
  border-color: var(--primary);
  outline: 2px solid var(--primary);
  outline-offset: -1px;
}

/* 2. Invalid / Error Form Controls (Overrides via cascade + :is() specificity) */
input:not([data-slot="combobox-input-group"] *):not([data-slot="autocomplete-input-group"] *):is([aria-invalid="true"], :user-invalid, [data-invalid], .border-error):focus-visible,
select:is([aria-invalid="true"], :user-invalid, [data-invalid], .border-error):focus-visible,
textarea:not([data-slot="prompt-input"] *):is([aria-invalid="true"], :user-invalid, [data-invalid], .border-error):focus-visible,
[data-slot="select-trigger"]:is([aria-invalid="true"], [data-invalid], .border-error):focus-visible,
[data-slot="combobox-input-group"]:is([data-invalid], .border-error, :has(:is([aria-invalid="true"], :user-invalid, [data-invalid]))):focus-within,
[data-slot="autocomplete-input-group"]:is([data-invalid], .border-error, :has(:is([aria-invalid="true"], :user-invalid, [data-invalid]))):focus-within {
  border-color: var(--error);
  outline: 2px solid var(--error);
  outline-offset: -1px;
}

/* 3. Discrete Buttons maintain floating 2px ring */
button:focus-visible:not([data-slot="select-trigger"]) {
  outline: 2px solid var(--primary);
  outline-offset: 2px;
}

/* 4. Dropdown / Menu / Listbox Items: Inset outline for Windows High Contrast mode, prevents overflow clipping */
[role="option"]:focus-visible,
[role="menuitem"]:focus-visible,
[role="menuitemcheckbox"]:focus-visible,
[role="menuitemradio"]:focus-visible {
  outline: 2px solid transparent;
  outline-offset: -2px;
}
/* 5. Compound Inner Inputs: Suppress internal ring when nested inside an input group so the outer group handles focus */
[data-slot="combobox-input-group"] input[data-slot="combobox-input"]:focus-visible,
[data-slot="autocomplete-input-group"] input[data-slot="autocomplete-input"]:focus-visible,
[data-slot="prompt-input"] textarea[data-slot="prompt-input-textarea"]:focus-visible {
  outline: none;
  border-color: transparent;
}

/* Autofill Credential Highlighting: maintains calibrated surface tokens and typography on browser autofill */
input:-webkit-autofill,
input:-webkit-autofill:hover,
input:-webkit-autofill:focus,
textarea:-webkit-autofill,
textarea:-webkit-autofill:hover,
textarea:-webkit-autofill:focus,
select:-webkit-autofill,
select:-webkit-autofill:hover,
select:-webkit-autofill:focus {
  -webkit-box-shadow: 0 0 0px 1000px var(--surface) inset !important;
  -webkit-text-fill-color: var(--on-surface) !important;
  caret-color: var(--primary);
  transition: background-color 5000s ease-in-out 0s;
}

input:autofill,
textarea:autofill,
select:autofill {
  box-shadow: 0 0 0px 1000px var(--surface) inset !important;
  filter: none;
}

/* Reduced motion preference: eliminates disruptive movement (transforms, translations, scale, bounce) while preserving accessible opacity fades */
@media (prefers-reduced-motion: reduce) {
  *, ::before, ::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  /* Allow calm, non-vestibular opacity crossfades for dialogs, popovers, and status changes */
  .transition-opacity,
  [data-open],
  [data-closed],
  [data-starting-style],
  [data-ending-style] {
    transition-property: opacity !important;
    transition-duration: var(--duration-quick, 150ms) !important;
    transform: none !important;
    filter: none !important;
  }
}

/* Canonical Motion & Transition Utilities */
@utility duration-stagger {
  transition-duration: var(--duration-stagger);
  animation-duration: var(--duration-stagger);
}

@utility duration-micro {
  transition-duration: var(--duration-micro);
  animation-duration: var(--duration-micro);
}

@utility duration-quick {
  transition-duration: var(--duration-quick);
  animation-duration: var(--duration-quick);
}

@utility duration-fast {
  transition-duration: var(--duration-fast);
  animation-duration: var(--duration-fast);
}

@utility duration-medium {
  transition-duration: var(--duration-medium);
  animation-duration: var(--duration-medium);
}

@utility duration-slow {
  transition-duration: var(--duration-slow);
  animation-duration: var(--duration-slow);
}

@utility duration-very-slow {
  transition-duration: var(--duration-very-slow);
  animation-duration: var(--duration-very-slow);
}

@utility duration-emphasis {
  transition-duration: var(--duration-emphasis);
  animation-duration: var(--duration-emphasis);
}

@utility stroke-dashoffset-0 {
  stroke-dashoffset: 0;
}

@utility animate-badge-pop {
  animation: badge-pop-in var(--duration-quick, 150ms) cubic-bezier(0.34, 1.36, 0.64, 1) both;
}

@utility animate-error-shake {
  animation: error-shake 300ms cubic-bezier(0.36, 0.07, 0.19, 0.97) both;
}

@utility animate-text-reveal {
  animation: text-reveal-rise var(--duration-very-slow, 500ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-step-forward {
  animation: step-slide-forward var(--duration-fast, 250ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-step-backward {
  animation: step-slide-backward var(--duration-fast, 250ms) var(--ease-standard, cubic-bezier(0.22, 1, 0.36, 1)) both;
}

@utility animate-roll-up {
  animation: roll-up 250ms cubic-bezier(0, 0, 0.2, 1) both;
}

@utility animate-roll-down {
  animation: roll-down 250ms cubic-bezier(0, 0, 0.2, 1) both;
}

@utility animate-check-pop {
  animation: t-check-circle-pop var(--duration-fast) var(--ease-smooth-out) forwards;
}

@utility animate-success-check {
  animation:
    t-check-fade var(--check-opacity-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) forwards,
    t-check-transform var(--check-transform-dur, 500ms) cubic-bezier(0.34, 1.35, 0.64, 1) forwards,
    t-check-blur var(--check-blur-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

@utility animate-check-draw {
  animation: t-check-draw var(--check-path-dur, 500ms) cubic-bezier(0.22, 1, 0.36, 1) var(--check-path-delay, 80ms) forwards;
}

@utility animate-digit-pop {
  animation: digit-pop-in var(--digit-dur, 500ms) cubic-bezier(0.34, 1.45, 0.64, 1) both;
}

@keyframes badge-pop-in {
  0% {
    transform: translate(-4px, 4px) scale(0);
    filter: blur(var(--blur-small, 2px));
    opacity: 0;
  }
  60% {
    transform: translate(0, 0) scale(1.15);
    filter: blur(0);
    opacity: 1;
  }
  100% {
    transform: translate(0, 0) scale(1);
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes error-shake {
  0% {
    transform: translateX(0);
  }
  16% {
    transform: translateX(calc(var(--shake-distance, 6px) * -1));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  33% {
    transform: translateX(var(--shake-overshoot, 4px));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  50% {
    transform: translateX(calc(var(--shake-overshoot, 4px) * -0.75));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  66% {
    transform: translateX(calc(var(--shake-overshoot, 4px) * 0.5));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  83% {
    transform: translateX(calc(var(--shake-overshoot, 4px) * -0.25));
    animation-timing-function: cubic-bezier(0.22, 1, 0.36, 1);
  }
  100% {
    transform: translateX(0);
  }
}

@keyframes text-reveal-rise {
  from {
    opacity: 0;
    transform: translateY(var(--distance-medium, 12px));
    filter: blur(var(--blur-medium, 3px));
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes step-slide-forward {
  from {
    opacity: 0;
    transform: translateX(var(--distance-base, 8px));
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes step-slide-backward {
  from {
    opacity: 0;
    transform: translateX(calc(var(--distance-base, 8px) * -1));
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes roll-up {
  from {
    opacity: 0;
    transform: translateY(4px);
    filter: blur(1px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes roll-down {
  from {
    opacity: 0;
    transform: translateY(-4px);
    filter: blur(1px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}

@keyframes t-check-circle-pop {
  0% {
    transform: scale(0.85);
    opacity: 0;
  }
  50% {
    transform: scale(1.05);
  }
  100% {
    transform: scale(1);
    opacity: 1;
  }
}

@keyframes t-check-fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes t-check-transform {
  from {
    transform: translateY(var(--check-y-amount, 40px)) rotate(var(--check-rotate-from, 80deg));
  }
  to {
    transform: translateY(0) rotate(0deg);
  }
}

@keyframes t-check-rotate {
  from {
    transform: rotate(var(--check-rotate-from, 80deg));
  }
  to {
    transform: rotate(0deg);
  }
}

@keyframes t-check-blur {
  from {
    filter: blur(var(--check-blur-from, var(--blur-medium, 3px)));
  }
  to {
    filter: blur(0px);
  }
}

@keyframes t-check-bob {
  from {
    transform: translateY(var(--check-y-amount, 40px));
  }
  to {
    transform: translateY(0);
  }
}

@keyframes t-check-draw {
  from {
    stroke-dashoffset: 26;
  }
  to {
    stroke-dashoffset: 0;
  }
}

@keyframes digit-pop-in {
  0% {
    transform: translate(
      calc(var(--digit-distance, 8px) * var(--digit-dir-x, 0)),
      calc(var(--digit-distance, 8px) * var(--digit-dir-y, 1))
    );
    opacity: 0;
    filter: blur(var(--digit-blur, 2px));
  }
  100% {
    transform: translate(0, 0);
    opacity: 1;
    filter: blur(0);
  }
}

/* Standardized Type Scale Utility Classes */
@utility text-display-lg {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  text-wrap: balance;
}

@utility text-display-sm {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.015em;
  text-wrap: balance;
}

@utility text-headline-lg {
  font-family: var(--font-heading);
  font-size: 2rem;
  font-weight: 600;
  line-height: 1.25;
  text-wrap: balance;
}

@utility text-headline-md {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.35;
  text-wrap: balance;
}

@utility text-headline-sm {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 600;
  line-height: 1.4;
  text-wrap: balance;
}

@utility text-body-lg {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 1.55;
  text-wrap: pretty;
}

@utility text-body-md {
  font-family: var(--font-sans);
  font-size: 1rem;
  font-weight: 400;
  line-height: 1.5;
  text-wrap: pretty;
}

@utility text-body-sm {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  line-height: 1.45;
  text-wrap: pretty;
}

@utility text-caption {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 400;
  line-height: 1.45;
}

@utility text-code-md {
  font-family: var(--font-mono);
  font-size: 0.875rem;
  font-weight: 400;
  line-height: 1.5;
}

@utility text-label-lg {
  font-family: var(--font-label);
  font-size: 0.875rem;
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: 0.01em;
}

@utility text-label-md {
  font-family: var(--font-label);
  font-size: 0.8125rem;
  font-weight: 600;
  line-height: 1.4;
  letter-spacing: 0.01em;
}

@utility text-label-sm {
  font-family: var(--font-label);
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.35;
  letter-spacing: 0.03em;
}

/* Global Heading & Body Text-Wrap Defaults */
h1, h2, h3, h4, h5, h6 {
  text-wrap: balance;
}

p, li {
  text-wrap: pretty;
}

/* Long-Form Content Rhythm (shadcn Typeset container system) */
.typeset {
  --typeset-font-body: var(--font-sans);
  --typeset-font-heading: var(--font-heading);
  --typeset-font-mono: var(--font-mono);
  --typeset-size: 1em;
  --typeset-leading: 1.5;
  --typeset-flow: 1.25em;

  font-family: var(--typeset-font-body);
  font-size: var(--typeset-size);
  line-height: var(--typeset-leading);
}

.typeset h1, .typeset h2, .typeset h3, .typeset h4 {
  font-family: var(--typeset-font-heading);
  font-weight: 600;
  line-height: 1.25;
  margin-top: calc(var(--typeset-flow) * 1.2);
  margin-bottom: calc(var(--typeset-flow) * 0.5);
  color: var(--on-surface);
  text-wrap: balance;
}

.typeset h1 {
  font-size: 1.875em;
}

.typeset h2 {
  font-size: 1.5em;
}

.typeset h3 {
  font-size: 1.25em;
}

.typeset h4 {
  font-size: 1.125em;
}

.typeset p, .typeset ul, .typeset ol {
  margin-top: 0;
  margin-bottom: var(--typeset-flow);
  color: var(--on-surface);
  text-wrap: pretty;
}

/* Typeset opt-out isolation for embedded cards & interactive primitives */
.typeset .not-typeset,
.typeset [data-not-typeset] {
  margin-top: var(--typeset-flow);
  margin-bottom: var(--typeset-flow);
  font-size: 1rem;
  line-height: 1.5;
}

.typeset .not-typeset p,
.typeset [data-not-typeset] p {
  margin-bottom: 0;
}

.typeset-chat {
  --typeset-flow: 1em;
  --typeset-leading: 1.5;
}

.typeset-guide {
  --typeset-size: 1.125em;
  --typeset-leading: 1.55;
  --typeset-flow: 1.5em;
}

.typeset-large {
  --typeset-size: 1.25em;
  --typeset-leading: 1.8;
  --typeset-flow: 1.75em;
}

/* WebMCP Agent Form interaction indicators */
form[data-tool-active] {
  outline: 2px dashed var(--primary);
  background-color: color-mix(in srgb, var(--primary-container) 10%, transparent);
}

/* Offscreen rendering optimization (MWG: defer-rendering-heavy-content) */
.content-visibility-auto {
  content-visibility: auto;
  contain-intrinsic-size: auto none auto 200px;
}

.content-visibility-hidden {
  content-visibility: hidden;
}

/* Scroll-Driven Reading Progress Indicator (MWG: scrollytelling / scroll-driven animations) */
@keyframes reading-progress-scale {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}

@supports ((animation-timeline: scroll()) and (animation-range: 0% 100%)) {
  .reading-progress-root-driven {
    transform-origin: left center;
    animation: reading-progress-scale linear;
    animation-timeline: scroll(root block);
    animation-range: 0% 100%;
    will-change: transform;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reading-progress-root-driven {
    animation: none !important;
    transform: none !important;
  }
}

/* View Transitions API (MWG: same-document-transitions) */
@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation: none !important;
  }
}

/* Precise Text Alignment: trims font leading/ghost whitespace for optical centering (MWG: precise-text-alignment) */
.box-trim {
  text-box-trim: trim-both;
  text-box-edge: cap alphabetic;
}

/* CSS Custom Highlight API: GPU-accelerated in-page search highlighting (MWG: highlight-text-ranges) */
::highlight(search-results) {
  background-color: var(--secondary-container);
  color: var(--on-secondary-container);
}

/* State-Aware Sticky Header: compositor-driven stuck elevation (MWG: state-aware-sticky-headers) */
.sticky-scroll-container {
  position: sticky;
  top: 0;
  container-type: scroll-state;
  container-name: sticky-nav;
}

@container sticky-nav scroll-state(stuck: top) {
  .sticky-nav-inner {
    background-color: var(--surface);
    box-shadow: var(--shadow-ambient);
    border-bottom-color: var(--outline-variant);
  }
}

.sticky-nav-inner.is-stuck {
  background-color: var(--surface);
  box-shadow: var(--shadow-ambient);
  border-bottom-color: var(--outline-variant);
}

/* Scrollspy Navigation: active target tracking (MWG: scrollspy) */
.scrollspy-nav {
  scroll-target-group: auto;
}

.scrollspy-link[aria-current="true"],
.scrollspy-link.\:target-current {
  color: var(--primary);
  font-weight: 600;
  border-left-color: var(--primary);
}

/* Container clipping boundary offset allowing floating focus rings and ambient drop-shadows to bleed unclipped (MWG: overflow-clipping-control) */
.clip-safe-shadow {
  overflow: clip;
  overflow-clip-margin: 8px;
}

/* Layout Containment Boundary: isolates reflow & recalculations in data-dense tables/grids (MWG: interactions-in-complex-layouts) */
.contain-layout {
  content-visibility: auto;
  contain-intrinsic-size: auto 300px;
}

@supports not (content-visibility: auto) {
  .contain-layout {
    contain: layout style;
  }
}

/* Asymmetric corner utilities for InlineAlert and Toast */
@utility rounded-r {
  border-top-right-radius: var(--radius-default);
  border-bottom-right-radius: var(--radius-default);
}

@utility rounded-r-default {
  border-top-right-radius: var(--radius-default);
  border-bottom-right-radius: var(--radius-default);
}

/* Expand Touch Target Beyond Visual Size (Good CSS #27, WCAG 2.2 SC 2.5.8) */
@utility touch-target-expanded {
  position: relative;
  &::after {
    content: "";
    position: absolute;
    inset: min(0px, calc((100% - 44px) / 2));
    pointer-events: auto;
  }
}

/* Compositor-Only Shadow Lift via Opacity Crossfade (Good CSS #35) */
@utility card-lift {
  position: relative;
  isolation: isolate;

  &::before,
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
  }

  &::before {
    box-shadow: var(--shadow-ambient);
    opacity: 1;
    transition: opacity var(--duration-fast) var(--ease-standard);
  }

  &::after {
    box-shadow: var(--shadow-ambient-hover);
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-standard);
  }

  @media (hover: hover) and (pointer: fine) {
    &:hover::before {
      opacity: 0;
    }
    &:hover::after {
      opacity: 1;
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  .card-lift::before,
  .card-lift::after {
    transition: none !important;
  }
}

/* CSS Subgrid Card Layouts (Good CSS #09) */
@utility card-subgrid {
  display: grid;
  grid-row: span 3;
  grid-template-rows: subgrid;
}

@utility card-grid-subgrid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 20rem), 1fr));
}

/* Font-Relative Optical Icon Sizing (Good CSS #23) */
@utility icon-inline {
  display: inline-flex;
  align-items: baseline;
  gap: 0.5em;

  & > svg,
  & > .material-symbols-outlined {
    flex: none;
    block-size: 1cap;
    inline-size: auto;
  }
}

@utility text-cap {
  font-size: 1.15cap;
  line-height: 1;
  vertical-align: baseline;
}

/* Safe Area Inset Utilities (Good CSS #47) */
@utility pt-safe {
  padding-top: max(var(--safe-top), 0px);
}

@utility pb-safe {
  padding-bottom: max(var(--safe-bottom), 0px);
}

@utility pl-safe {
  padding-left: max(var(--safe-left), 0px);
}

@utility pr-safe {
  padding-right: max(var(--safe-right), 0px);
}

@utility p-safe {
  padding-top: max(var(--safe-top), 0px);
  padding-bottom: max(var(--safe-bottom), 0px);
  padding-left: max(var(--safe-left), 0px);
  padding-right: max(var(--safe-right), 0px);
}

/* Safe Alignment Utilities for Scrollable Containers (Good CSS #13) */
@utility justify-safe-center {
  justify-content: safe center;
}

@utility items-safe-center {
  align-items: safe center;
}

/* Whole Card Clickable Link Pattern (Good CSS #28, Heydon Pickering Inclusive Cards) */
@utility card-link {
  position: static;
  &::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
  }
  &:focus-visible {
    outline: 2px solid transparent;
  }
}

@utility card-interactive-child {
  position: relative;
  z-index: 1;
}
